package app.pulso.radio;

import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.media.*;
import android.os.*;
import android.util.Base64;
import androidx.core.app.NotificationCompat;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class RadioService extends Service {
  public static volatile boolean appVisible=false;
  public static volatile boolean running=false;
  private static final String ORIGIN="https://pulso-radio-matheus.airycake256.chatgpt.site";
  private static final int SERVICE_ID=101, ALERT_ID=102;
  private ScheduledExecutorService network;
  private ExecutorService player;
  private PowerManager.WakeLock wakeLock;
  private AudioTrack track;
  private MediaPlayer tone;
  private volatile boolean stopped=false;
  private long lastHeartbeat=0,lastRing=0;
  private final Map<String,TreeMap<Integer,JSONObject>> reorder=new HashMap<>();
  private final Map<String,Integer> expected=new HashMap<>();
  private final Map<String,Long> gapSince=new HashMap<>();
  private android.content.SharedPreferences prefs(){return getSharedPreferences("pulso_native",MODE_PRIVATE);}
  private String value(String key){return prefs().getString(key,"");}

  @Override public void onCreate(){super.onCreate();channels();network=Executors.newSingleThreadScheduledExecutor();player=Executors.newSingleThreadExecutor();}
  private void channels(){if(Build.VERSION.SDK_INT>=26){NotificationManager manager=getSystemService(NotificationManager.class);NotificationChannel status=new NotificationChannel("pulso_radio_service","Rádio em segundo plano",NotificationManager.IMPORTANCE_LOW);status.setSound(null,null);manager.createNotificationChannel(status);NotificationChannel calls=new NotificationChannel("pulso_radio_calls","Chamadas do rádio",NotificationManager.IMPORTANCE_HIGH);calls.setSound(null,null);calls.enableVibration(true);calls.setVibrationPattern(new long[]{0,100,50,100});manager.createNotificationChannel(calls);}}
  private PendingIntent open(){return PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
  private Notification ongoing(String message){Intent stop=new Intent(this,RadioService.class).setAction("STOP");PendingIntent action=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new NotificationCompat.Builder(this,"pulso_radio_service").setSmallIcon(R.drawable.ic_radio_notification).setContentTitle("Pulso • Rádio ativo").setContentText(message).setContentIntent(open()).setOngoing(true).setOnlyAlertOnce(true).setCategory(NotificationCompat.CATEGORY_SERVICE).addAction(0,"Desligar rádio",action).build();}
  @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"STOP".equals(intent.getAction())){prefs().edit().putBoolean("enabled",false).apply();network.execute(()->{try{JSONObject body=new JSONObject().put("enabled",false).put("foreground",false).put("name",value("name"));api("heartbeat","POST",body);}catch(Exception ignored){}stopSelf();});return START_NOT_STICKY;}if(!prefs().getBoolean("enabled",false)||value("code").isEmpty()){stopSelf();return START_NOT_STICKY;}Notification notification=ongoing("Conectado para receber voz e mensagens");if(Build.VERSION.SDK_INT>=34)startForeground(SERVICE_ID,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK|ServiceInfo.FOREGROUND_SERVICE_TYPE_REMOTE_MESSAGING);else if(Build.VERSION.SDK_INT>=29)startForeground(SERVICE_ID,notification,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(SERVICE_ID,notification);if(!running){running=true;PowerManager pm=getSystemService(PowerManager.class);wakeLock=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Pulso:RadioReceiver");wakeLock.setReferenceCounted(false);wakeLock.acquire(60*60*1000L);network.scheduleWithFixedDelay(this::tick,500,650,TimeUnit.MILLISECONDS);}return START_STICKY;}
  private JSONObject api(String action,String method,JSONObject body)throws Exception{URL url=new URL(ORIGIN+"/api/radio/"+action);HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(7000);connection.setReadTimeout(9000);connection.setRequestMethod(method);connection.setRequestProperty("Authorization","Bearer "+value("code")+"."+value("secret"));connection.setRequestProperty("Accept","application/json");if(body!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] bytes=body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);connection.setFixedLengthStreamingMode(bytes.length);try(OutputStream output=connection.getOutputStream()){output.write(bytes);}}int result=connection.getResponseCode();InputStream input=result<400?connection.getInputStream():connection.getErrorStream();String text;try(input;ByteArrayOutputStream out=new ByteArrayOutputStream()){if(input!=null){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1)out.write(buffer,0,n);}text=out.toString("UTF-8");}finally{connection.disconnect();}if(result>=400)throw new IOException("HTTP "+result);return new JSONObject(text);}
  private void tick(){if(stopped||!prefs().getBoolean("enabled",false))return;if(wakeLock!=null&&!wakeLock.isHeld())wakeLock.acquire(60*60*1000L);if(appVisible)return;try{long now=System.currentTimeMillis();if(now-lastHeartbeat>10000){api("heartbeat","POST",new JSONObject().put("enabled",true).put("foreground",false).put("name",value("name")));lastHeartbeat=now;getSystemService(NotificationManager.class).notify(SERVICE_ID,ongoing("Recebendo em segundo plano • toque para abrir"));}long after=prefs().getLong("cursor",0);JSONArray packets=api("poll?after="+after,"GET",null).optJSONArray("packets");if(packets!=null)for(int i=0;i<packets.length();i++){JSONObject packet=packets.getJSONObject(i);if(appVisible)break;String selected=value("contact");if(selected.isEmpty()||selected.equals(packet.optString("sender")))handle(packet);after=Math.max(after,packet.optLong("id"));prefs().edit().putLong("cursor",after).apply();}flushGaps();}catch(Exception error){getSystemService(NotificationManager.class).notify(SERVICE_ID,ongoing("Reconectando à internet…"));}}
  private void handle(JSONObject packet)throws Exception{JSONObject data=new JSONObject(packet.getString("payload"));String type=data.optString("type"),from=packet.optString("sender");if(type.equals("radio-call")){if(data.optString("action").equals("request")){if(data.optLong("expires",Long.MAX_VALUE)<System.currentTimeMillis())return;saveBacklog(packet);alert("Chamada TALK de "+from,"Toque para abrir e aceitar");if(prefs().getBoolean("beep",true))player.execute(()->playTone("call"));}else{saveBacklog(packet);if(data.optString("action").equals("end"))prefs().edit().putString("talkSession","").putString("expiredTalkSession",data.optString("id")).apply();}return;}if(!data.optString("session").isEmpty()&&(!data.optString("session").equals(value("talkSession"))||!from.equals(value("contact"))))return;if(type.equals("talk")&&data.optBoolean("on")){String display=value("contactName");if(display.isEmpty()||!from.equals(value("contact")))display=from;alert(display+" chamou no rádio","Recebendo voz • toque para abrir");if(data.optString("session").isEmpty()&&prefs().getBoolean("directTone",false)&&prefs().getBoolean("beep",true)&&System.currentTimeMillis()-lastRing>1800){lastRing=System.currentTimeMillis();player.execute(()->playTone("call"));}}else if(type.equals("text")){saveBacklog(packet);String display=value("contactName");if(display.isEmpty())display=from;alert("Mensagem de "+display,data.optString("text"));player.execute(()->playTone("message"));}else if(type.equals("pcm")){String burst=data.optString("burst","legacy");int seq=data.optInt("seq",-1);if(seq<0){enqueueAudio(data);return;}if(reorder.size()>8){reorder.clear();expected.clear();gapSince.clear();}TreeMap<Integer,JSONObject> packets=reorder.computeIfAbsent(burst,k->new TreeMap<>());int next=expected.getOrDefault(burst,0);if(seq<next)return;packets.put(seq,data);gapSince.putIfAbsent(burst,System.currentTimeMillis());flush(burst,false);}}
  private synchronized void saveBacklog(JSONObject packet){try{JSONArray messages=new JSONArray(prefs().getString("backlog","[]"));JSONArray result=new JSONArray();for(int i=Math.max(0,messages.length()-39);i<messages.length();i++)result.put(messages.get(i));result.put(packet);prefs().edit().putString("backlog",result.toString()).apply();}catch(Exception ignored){}}
  private void flush(String burst,boolean skip){TreeMap<Integer,JSONObject> packets=reorder.get(burst);if(packets==null||packets.isEmpty())return;int next=expected.getOrDefault(burst,0);if(skip&&!packets.containsKey(next))next=packets.firstKey();while(packets.containsKey(next)){enqueueAudio(packets.remove(next));next++;}expected.put(burst,next);gapSince.put(burst,System.currentTimeMillis());}
  private void flushGaps(){long now=System.currentTimeMillis();for(String burst:new ArrayList<>(reorder.keySet()))if(now-gapSince.getOrDefault(burst,now)>1300)flush(burst,true);}
  private void alert(String title,String message){Notification notification=new NotificationCompat.Builder(this,"pulso_radio_calls").setSmallIcon(R.drawable.ic_radio_notification).setContentTitle(title).setContentText(message).setContentIntent(open()).setAutoCancel(true).setCategory(NotificationCompat.CATEGORY_MESSAGE).setPriority(NotificationCompat.PRIORITY_HIGH).setVisibility(NotificationCompat.VISIBILITY_PRIVATE).build();try{getSystemService(NotificationManager.class).notify(ALERT_ID,notification);}catch(SecurityException ignored){}}
  private void playTone(String kind){String choice=value(kind.equals("message")?"messageSound":"callSound");if(choice.isEmpty())choice=kind.equals("message")?"ping":"original";if(choice.equals("off"))return;int resource;switch(choice){case "digital":resource=R.raw.digital;break;case "soft":resource=R.raw.soft;break;case "ping":resource=R.raw.ping;break;case "chime":resource=R.raw.chime;break;default:resource=R.raw.radio_chamada;}if(stopped)return;CountDownLatch done=new CountDownLatch(1);MediaPlayer local=null;try{local=new MediaPlayer();tone=local;local.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION_COMMUNICATION_REQUEST).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());if(choice.startsWith("custom-")){java.io.File file=new java.io.File(getFilesDir(),"tone-"+(kind.equals("message")?"message":"call")+".audio");if(!file.isFile())throw new java.io.FileNotFoundException();local.setDataSource(file.getAbsolutePath());}else{android.content.res.AssetFileDescriptor fd=getResources().openRawResourceFd(resource);local.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());fd.close();}local.setOnCompletionListener(p->done.countDown());local.setOnErrorListener((p,what,extra)->{done.countDown();return true;});local.prepare();local.start();done.await(10,TimeUnit.SECONDS);}catch(Exception ignored){done.countDown();}finally{if(local!=null)try{local.release();}catch(Exception ignored){}tone=null;}}
  private void enqueueAudio(JSONObject data){String audio=data.optString("audio");player.execute(()->{if(stopped)return;try{byte[] bytes=Base64.decode(audio,Base64.DEFAULT);if(track==null){int size=Math.max(AudioTrack.getMinBufferSize(16000,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT),64000);track=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(16000).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).setEncoding(AudioFormat.ENCODING_PCM_16BIT).build()).setBufferSizeInBytes(size).setTransferMode(AudioTrack.MODE_STREAM).build();track.play();}track.write(bytes,0,bytes.length,AudioTrack.WRITE_BLOCKING);}catch(Exception ignored){}});}
  @Override public void onDestroy(){stopped=true;running=false;network.shutdownNow();player.shutdownNow();try{if(tone!=null)tone.release();if(track!=null){track.pause();track.flush();track.release();}}catch(Exception ignored){}if(wakeLock!=null&&wakeLock.isHeld())wakeLock.release();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
  @Override public IBinder onBind(Intent intent){return null;}
}
